class Base {
    virtual void virtualFunc();  // Declares a virtual function, triggering vtable generation
};

class Derived : public Base {
    void virtualFunc() override;  // Overrides the virtual function, adding an entry in Derived's vtable
};

// Implementation notes: The compiler adds a vptr as the first member in the class layout. For example, sizeof(Base) includes the size of the vptr plus any non-static data members. In constructors, the compiler inserts code like: this->vptr = &Derived::vtable; to set the correct vtable pointer.
